/**
 * Mem0AI memory service.
 *
 * A persistent, per-user memory store (backed by localforage, like the
 * MemoryContext store) with lexical relevance search. It never produces
 * character text itself: responses that use memory context are generated by
 * the language model through DeepTreeEchoOpenAIService (configured API or a
 * verified locally served model).
 */
import localforage from "localforage";
import { DeepTreeEchoOpenAIService } from "./openaiService";
import {
  Mem0AISummary,
  Mem0ry,
  Mem0ryQueryOptions,
  Mem0rySearchResult,
  Mem0ryStats,
  Mem0ryType,
} from "../types/Mem0AI";

export interface Mem0ryInput {
  title: string;
  content: string;
  tags?: string[];
  type?: Mem0ryType;
  context?: string;
  metadata?: Record<string, unknown>;
}

export interface Mem0ryListOptions {
  type?: Mem0ryType;
  tags?: string[];
  limit?: number;
}

const MEMORY_TYPES: Mem0ryType[] = [
  "episodic",
  "semantic",
  "procedural",
  "declarative",
  "implicit",
  "associative",
  "memory",
];

const DAY_MS = 24 * 60 * 60 * 1000;

const tokenize = (text: string): string[] =>
  text
    .toLowerCase()
    .split(/\W+/)
    .filter(token => token.length > 2);

class Mem0AIService {
  private static instance: Mem0AIService;
  private userId: string | null = null;
  private memories: Mem0ry[] = [];
  private loaded: Promise<void> | null = null;

  private constructor() {}

  public static getInstance(): Mem0AIService {
    if (!Mem0AIService.instance) {
      Mem0AIService.instance = new Mem0AIService();
    }
    return Mem0AIService.instance;
  }

  /**
   * Select the user's memory store and optionally set an API key. The model
   * itself is resolved by modelProvider (configured API/base URL or a
   * verified local model), so the store works without a key.
   */
  public initialize(apiKey: string | undefined, userId: string): void {
    if (apiKey) {
      DeepTreeEchoOpenAIService.getInstance().setApiKey(apiKey);
    }
    if (this.userId !== userId) {
      this.userId = userId;
      this.memories = [];
      this.loaded = this.load();
    }
  }

  /** True once a user's memory store is selected. */
  public isInitialized(): boolean {
    return this.userId !== null;
  }

  private get storageKey(): string {
    return `mem0ai_memories_${this.userId}`;
  }

  private async load(): Promise<void> {
    const stored = await localforage.getItem<Mem0ry[]>(this.storageKey);
    this.memories = stored || [];
  }

  private async ready(): Promise<void> {
    if (!this.userId || !this.loaded) {
      throw new Error("Mem0AI is not initialized");
    }
    await this.loaded;
  }

  private async persist(): Promise<void> {
    await localforage.setItem(this.storageKey, this.memories);
  }

  public async addMemory(input: Mem0ryInput): Promise<Mem0ry> {
    await this.ready();
    const now = new Date().toISOString();
    const memory: Mem0ry = {
      id: `mem0_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
      title: input.title,
      content: input.content,
      tags: input.tags || [],
      type: input.type || "memory",
      context: input.context,
      metadata: input.metadata,
      createdAt: now,
      updatedAt: now,
    };
    this.memories.push(memory);
    await this.persist();
    return memory;
  }

  public async getMemory(id: string): Promise<Mem0ry | null> {
    await this.ready();
    return this.memories.find(memory => memory.id === id) || null;
  }

  public async updateMemory(
    id: string,
    updates: Partial<Mem0ryInput>
  ): Promise<Mem0ry | null> {
    await this.ready();
    const index = this.memories.findIndex(memory => memory.id === id);
    if (index === -1) return null;
    const updated: Mem0ry = {
      ...this.memories[index],
      ...updates,
      tags: updates.tags ?? this.memories[index].tags,
      updatedAt: new Date().toISOString(),
    };
    this.memories[index] = updated;
    await this.persist();
    return updated;
  }

  public async deleteMemory(id: string): Promise<void> {
    await this.ready();
    this.memories = this.memories.filter(memory => memory.id !== id);
    await this.persist();
  }

  public async listMemories(
    options: Mem0ryListOptions = {}
  ): Promise<Mem0ry[]> {
    await this.ready();
    let result = [...this.memories];
    if (options.type) {
      result = result.filter(memory => memory.type === options.type);
    }
    if (options.tags && options.tags.length > 0) {
      result = result.filter(memory =>
        options.tags!.every(tag => memory.tags.includes(tag))
      );
    }
    result.sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
    return options.limit ? result.slice(0, options.limit) : result;
  }

  /**
   * Lexical relevance search: similarity is the fraction of query terms that
   * occur in the memory's title, content, tags or context.
   */
  public async searchMemories(
    query: string,
    options: Mem0ryQueryOptions = {}
  ): Promise<Mem0rySearchResult[]> {
    await this.ready();
    const queryTerms = Array.from(new Set(tokenize(query)));
    if (queryTerms.length === 0) return [];

    const threshold = options.threshold ?? 0;
    const start = options.timeframe?.start?.getTime();
    const end = options.timeframe?.end?.getTime();

    return this.memories
      .filter(memory => !options.type || memory.type === options.type)
      .filter(
        memory =>
          !options.includeTags ||
          options.includeTags.every(tag => memory.tags.includes(tag))
      )
      .filter(
        memory =>
          !options.excludeTags ||
          !options.excludeTags.some(tag => memory.tags.includes(tag))
      )
      .filter(memory => {
        const created = new Date(memory.createdAt).getTime();
        return (
          (start === undefined || created >= start) &&
          (end === undefined || created <= end)
        );
      })
      .map(memory => {
        const terms = new Set(
          tokenize(
            [
              memory.title,
              memory.content,
              memory.context || "",
              ...memory.tags,
            ].join(" ")
          )
        );
        const hits = queryTerms.filter(term => terms.has(term)).length;
        return {
          id: memory.id,
          content: `${memory.title}\n${memory.content}`,
          metadata: {
            ...memory.metadata,
            tags: memory.tags,
            type: memory.type,
          },
          similarity: hits / queryTerms.length,
        };
      })
      .filter(result => result.similarity > 0 && result.similarity >= threshold)
      .sort((a, b) => b.similarity - a.similarity)
      .slice(0, options.limit ?? 10);
  }

  public async getMemoryStats(): Promise<Mem0ryStats> {
    await this.ready();
    const byType = Object.fromEntries(
      MEMORY_TYPES.map(type => [type, 0])
    ) as Record<Mem0ryType, number>;
    const byTag: Record<string, number> = {};
    const dayAgo = Date.now() - DAY_MS;
    let recentlyAdded = 0;
    let recentlyAccessed = 0;

    for (const memory of this.memories) {
      byType[memory.type || "memory"] += 1;
      memory.tags.forEach(tag => {
        byTag[tag] = (byTag[tag] || 0) + 1;
      });
      if (new Date(memory.createdAt).getTime() > dayAgo) recentlyAdded += 1;
      if (new Date(memory.updatedAt).getTime() > dayAgo) recentlyAccessed += 1;
    }

    return {
      total: this.memories.length,
      byType,
      byTag,
      recentlyAdded,
      recentlyAccessed,
    };
  }

  /** Ask the model to analyse the stored memories. */
  public async generateMemorySummary(): Promise<Mem0AISummary> {
    await this.ready();
    if (this.memories.length === 0) {
      throw new Error("No memories stored to summarize");
    }

    const corpus = this.memories
      .slice(-50)
      .map(
        (memory, i) =>
          `[${i + 1}] (${memory.type || "memory"}; tags: ${memory.tags.join(", ")}) ${memory.title}: ${memory.content.substring(0, 500)}`
      )
      .join("\n");

    const raw = await DeepTreeEchoOpenAIService.getInstance().generateResponse(
      `Analyse these stored memories:\n${corpus}\n\nReturn only a JSON object with string-array fields "insights", "frequentConcepts", "knowledgeGaps" and "recommendations".`,
      {
        systemPrompt:
          "You analyse a user's memory store and reply with strict JSON only.",
        creativityLevel: "analytical",
        temperature: 0.3,
      }
    );

    const json = raw.slice(raw.indexOf("{"), raw.lastIndexOf("}") + 1);
    const parsed = JSON.parse(json) as Partial<Mem0AISummary>;
    const asStrings = (value: unknown): string[] =>
      Array.isArray(value) ? value.map(String) : [];
    return {
      insights: asStrings(parsed.insights),
      frequentConcepts: asStrings(parsed.frequentConcepts),
      knowledgeGaps: asStrings(parsed.knowledgeGaps),
      recommendations: asStrings(parsed.recommendations),
    };
  }

  /**
   * Generate a model response with relevant stored memories as context.
   */
  public async generateResponseWithMemoryContext(
    query: string,
    conversationHistory: Array<{ role: "user" | "assistant"; content: string }>,
    options: {
      model?: string;
      temperature?: number;
      maxTokens?: number;
      creativityLevel?:
        | "balanced"
        | "analytical"
        | "creative"
        | "philosophical";
      /** Prompt-template instructions for this reply. */
      systemPrompt?: string;
      onToken?: (token: string) => void;
    } = {}
  ): Promise<string> {
    const relevant = await this.searchMemories(query, { limit: 5 });
    const last = conversationHistory[conversationHistory.length - 1];
    const history =
      last && last.role === "user" && last.content === query
        ? conversationHistory
        : [...conversationHistory, { role: "user" as const, content: query }];
    return DeepTreeEchoOpenAIService.getInstance().generateResponseWithMemory(
      query,
      history,
      relevant.map(result => result.content),
      options
    );
  }
}

/** React hook: returns the shared (stable) Mem0AI service instance. */
export const useMem0AI = () => Mem0AIService.getInstance();

export default Mem0AIService;
